-- address tile
with bounds as ( select st_tileenvelope($1, $2, $3) as geom_3857, st_transform(st_tileenvelope($4, $5, $6), 4326) as geom_4326 ), tile_rows as ( select a.id, a.display_name as "displayName", st_asmvtgeom( st_transform(a.geom, 3857), bounds.geom_3857, extent => $7, buffer => $8 ) as geom from addresses a cross join bounds where a.organization_id = $9 and a.deleted_at is null and position(lower($10) in lower(a.display_name)) > 0 and exists ( select 1 from regions rf where rf.id = any($11::uuid[]) and rf.organization_id = a.organization_id and rf.deleted_at is null and rf.geom && a.geom and st_intersects(rf.geom, a.geom) ) and a.geom && bounds.geom_4326 and st_intersects(a.geom, bounds.geom_4326) ) select coalesce(st_asmvt(tile_rows, $12::text, $13, 'geom'), ''::bytea) as tile from tile_rows

-- address extent
with extent as ( select st_extent(a.geom) as box from addresses a where a.organization_id = $1 and a.deleted_at is null and position(lower($2) in lower(a.display_name)) > 0 and exists ( select 1 from regions rf where rf.id = any($3::uuid[]) and rf.organization_id = a.organization_id and rf.deleted_at is null and rf.geom && a.geom and st_intersects(rf.geom, a.geom) ) ) select st_xmin(box) as "west", st_ymin(box) as "south", st_xmax(box) as "east", st_ymax(box) as "north" from extent

-- region tile
with bounds as ( select st_tileenvelope($1, $2, $3) as geom_3857, st_transform(st_tileenvelope($4, $5, $6), 4326) as geom_4326 ), tile_rows as ( select r.id, r.name, r.region_folder_id as "regionFolderId", st_asmvtgeom( st_transform(r.geom, 3857), bounds.geom_3857, extent => $7, buffer => $8 ) as geom from regions r cross join bounds where r.organization_id = $9 and r.deleted_at is null and r.id = any($10::uuid[]) and r.region_folder_id is null and position(lower($11) in lower(r.name)) > 0 and r.geom && bounds.geom_4326 and st_intersects(r.geom, bounds.geom_4326) ) select coalesce(st_asmvt(tile_rows, $12::text, $13, 'geom'), ''::bytea) as tile from tile_rows

-- region extent
with extent as ( select st_extent(r.geom) as box from regions r where r.organization_id = $1 and r.deleted_at is null and r.id = any($2::uuid[]) and r.region_folder_id is null and position(lower($3) in lower(r.name)) > 0 ) select st_xmin(box) as "west", st_ymin(box) as "south", st_xmax(box) as "east", st_ymax(box) as "north" from extent